import { test, expect } from './fixtures';

test('shows function tooltip when entering a formula in transaction amount', async ({ page }) => {
  await page.goto('/');

  await page.getByRole('link', { name: 'Accounts' }).first().click();
  await page.getByRole('link', { name: /Bank of America/ }).first().click();

  const addTransactionButton = page
    .getByRole('button', { name: /add new|new transaction/i })
    .first();
  await addTransactionButton.click();

  const amountInput = page
    .locator('input[inputmode="decimal"], input[placeholder="0.00"]')
    .first();
  await amountInput.click();
  await amountInput.type('=');

  const tooltip = page.locator('functiontooltip, [class*="functiontooltip"]');
  await expect(tooltip).toBeVisible();
});

